import jwt
import time
import uuid
from cryptography.hazmat.primitives.asymmetric import rsa
from cryptography.hazmat.primitives import serialization


class JWTManager:
    def __init__(self, private_key=None, public_key=None):
        if private_key is None:
            self.private_key = rsa.generate_private_key(
                public_exponent=65537,
                key_size=2048,
            )
        else:
            self.private_key = private_key

        if public_key is None:
            self.public_key = self.private_key.public_key()
        else:
            self.public_key = public_key

    def get_private_pem(self):
        return self.private_key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.PKCS8,
            encryption_algorithm=serialization.NoEncryption(),
        ).decode("utf-8")

    def get_public_pem(self):
        return self.public_key.public_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PublicFormat.SubjectPublicKeyInfo,
        ).decode("utf-8")

    def generate_token(self, payload, expiration_seconds=3600):
        now = int(time.time())
        claims = {
            "iat": now,
            "exp": now + expiration_seconds,
            "jti": str(uuid.uuid4()),
            **payload,
        }
        token = jwt.encode(
            claims,
            self.private_key,
            algorithm="RS256",
        )
        return token

    def validate_token(self, token, leeway=10):
        try:
            decoded = jwt.decode(
                token,
                self.public_key,
                algorithms=["RS256"],
                leeway=leeway,
            )
            return {"valid": True, "payload": decoded}
        except jwt.ExpiredSignatureError:
            return {"valid": False, "error": "Token expirado"}
        except jwt.InvalidTokenError as e:
            return {"valid": False, "error": f"Token inválido: {str(e)}"}


if __name__ == "__main__":
    manager = JWTManager()

    token = manager.generate_token(
        payload={
            "sub": "user_123",
            "name": "João Silva",
            "roles": ["admin", "user"],
        },
        expiration_seconds=60,
    )
    print(f"Token gerado:\n{token}\n")

    result = manager.validate_token(token)
    print(f"Validação imediata: {result}\n")

    expired_token = manager.generate_token(
        payload={"sub": "user_456"},
        expiration_seconds=-10,
