  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
    new winston.transports.Console({
      format: winston.format.simple()
    })
  ]
});

// ==================== GPU SETUP ====================
const gpu = new GPU();

/**
 * GPU kernel for pixel value transformation (windowing/leveling)
 */
const transformPixelsKernel = gpu.createKernel(function(pixels, windowCenter, windowWidth, rescaleSlope, rescaleIntercept) {
  const i = this.thread.x;
  if (i < pixels.length) {
    const raw = pixels[i] * rescaleSlope + rescaleIntercept;
    const lower = windowCenter - windowWidth / 2;
    const upper = windowCenter + windowWidth / 2;
    if (raw <= lower) {
      pixels[i] = 0;
    } else if (raw >= upper) {
      pixels[i] = 255;
    } else {
      pixels[i] = ((raw - lower) / windowWidth) * 255;
    }
