# Script Node.js para Conversão de Documentos HTML/JSON em PDF

Abaixo apresento uma solução completa usando bibliotecas npm especializadas para gerar PDFs com formatação visual avançada, suporte a tabelas, cabeçalhos, rodapés e estilos personalizados.

## 1. Instalação das Dependências

```bash
npm init -y
npm install pdfkit handlebars puppeteer sharp
```

## 2. Estrutura do Projeto

```
projeto-pdf/
├── package.json
├── converter.js
├── templates/
│   └── relatorio.html
├── data/
│   └── exemplo.json
└── output/
```

## 3. Script Principal (`converter.js`)

```javascript
// converter.js
const fs = require('fs');
const path = require('path');
const PDFDocument = require('pdfkit');
const Handlebars = require('handlebars');
const puppeteer = require('puppeteer');
const sharp = require('sharp');

class PDFConverter {
    constructor(outputDir = './output') {
        this.outputDir = outputDir;
        if (!fs.existsSync(outputDir)) {
            fs.mkdirSync(outputDir, { recursive: true });
        }
        this.registerHandlebarsHelpers();
    }

    // Helpers personalizados para Handlebars
    registerHandlebarsHelpers() {
        Handlebars.registerHelper('formatCurrency', (value) => {
            return new Intl.NumberFormat('pt-BR', {
                style: 'currency',
                currency: 'BRL'
            }).format(value);
        });

        Handlebars.registerHelper('formatDate', (date) => {
            return new Date(date).toLocaleDateString('pt-BR');
        });

        Handlebars.registerHelper('eq', (a, b) => a === b);
        Handlebars.registerHelper('gt', (a, b) => a > b);
    }

    // ============== MÉTODO 1: HTML para PDF (via Puppeteer) ==============
    async htmlToPdf(htmlContent, outputName = 'documento.pdf', options = {}) {
        const browser = await puppeteer.launch({
            headless: 'new',
            args: ['--no-sandbox', '--disable-setuid-sandbox']
        });

        try {
            const page = await browser.newPage();

            // Configurar cabeçalhos/rodapés se fornecidos
            if (options.headerTemplate || options.footerTemplate) {
                await page.evaluateOnNewDocument(() => {
                    window.PDFConfig = {
                        headerTemplate: arguments[0].headerTemplate,
                        footerTemplate: arguments[0].footerTemplate
                    };
                }, options);
            }

            await page.setContent(htmlContent, {
                waitUntil: 'networkidle0'
            });

            const pdfBuffer = await page.pdf({
                format: options.format || 'A4',
                printBackground: true,
                margin: options.margin || {
                    top: '20mm',
                    right: '15mm',
                    bottom: '20mm',
                    left: '15mm'
                },
                displayHeaderFooter: !!(options.headerTemplate || options.footerTemplate),
                headerTemplate: options.headerTemplate || '<div></div>',
                footerTemplate: options.footerTemplate || `
                    <div style="font-size: 9px; width: 100%; text-align: center; padding: 0 15mm;">
                        <span>Página <span class="pageNumber"></span> de <span class="totalPages"></span></span>
                    </div>
                `
            });

            const outputPath = path.join(this.outputDir, outputName);
            fs.writeFileSync(outputPath, pdfBuffer);

            console.log(`✅ PDF gerado com sucesso: ${outputPath}`);
            return outputPath;
        } finally {
            await browser.close();
        }
    }

