# Conversor de HTML/JSON para PDF

Abaixo está um script Node.js que converte documentos HTML e JSON em PDFs formatados, usando `pdfkit` e `pdfkit-table` (bibliotecas públicas verificadas no npm).

## Instalação

```bash
npm init -y
npm install pdfkit pdfkit-table
```

## Script: `converter.js`

```javascript
const PDFDocument = require('pdfkit');
const PDFTable = require('pdfkit-table');
const fs = require('fs');

// ============================================
// 1. CONVERSOR DE HTML SIMPLIFICADO PARA PDF
// ============================================
async function htmlToPdf(htmlContent, outputPath) {
    return new Promise((resolve, reject) => {
        try {
            const doc = new PDFDocument({ margin: 50 });
            const stream = fs.createWriteStream(outputPath);
            doc.pipe(stream);

            // Remove tags HTML básicas para extração de texto
            const text = htmlContent
                .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
                .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
                .replace(/<br\s*\/?>/gi, '\n')
                .replace(/<\/p>/gi, '\n\n')
                .replace(/<\/h[1-6]>/gi, '\n\n')
                .replace(/<[^>]+>/g, '')
                .replace(/&nbsp;/g, ' ')
                .replace(/&amp;/g, '&')
                .replace(/&lt;/g, '<')
                .replace(/&gt;/g, '>')
                .trim();

            // Detecta títulos H1 para formatação
            const lines = text.split('\n');
            let isFirstLine = true;

            lines.forEach((line) => {
                const trimmed = line.trim();
                if (!trimmed) return;

                // Heurística: primeira linha é o título principal
                if (isFirstLine) {
                    doc.fontSize(22).font('Helvetica-Bold').fillColor('#2C3E50');
                    doc.text(trimmed, { align: 'center' });
                    doc.moveDown(1);
                    isFirstLine = false;
                } else {
                    doc.fontSize(11).font('Helvetica').fillColor('#000000');
                    doc.text(trimmed, { align: 'justify' });
                    doc.moveDown(0.5);
                }
            });

            doc.end();
            stream.on('finish', () => resolve(outputPath));
            stream.on('error', reject);
        } catch (err) {
            reject(err);
        }
    });
}

